def rounded_avg(n: int, m: int) -> str | int:
    if n > m:
        return -1
    total_sum = sum(range(n, m + 1))
    count = m - n + 1
    average = total_sum // count
    if (total_sum % count) >= (count // 2):
        average += 1
    return bin(average)
